INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('581b9330-4b3f-4a38-992b-91a66c069609', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$81. óra: Százalékszámítás$q$, $q$1 egész = 100%, 1% fogalma (századrész), százalék és törtrész kapcsolata.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "a0ce5bc7-3afe-4620-beb6-ca2639012ea6", "text": "Mit jelent a 1% (egy százalék) fogalma?", "type": "multiple-choice", "options": [{"id": "45b16499-8cde-4ecd-8fb7-9185a2af559e", "text": "Az egész mennyiség 1/100-ad részét (századrészét)", "isCorrect": true}, {"id": "c151f493-e94b-41f2-bb04-79e2e002b30b", "text": "Az egész 1/10-ed részét", "isCorrect": false}, {"id": "3e193ebb-a5e7-4126-ac3c-f3f928d4ee80", "text": "100 egészet", "isCorrect": false}, {"id": "64cb687a-ab4d-4578-8379-362f95bfcc96", "text": "Az egész felét", "isCorrect": false}], "timeLimit": 15}, {"id": "03101b7e-cae2-46ce-8e78-7a4afffff933", "text": "Hány százalék felel meg a teljes egésznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "89c0e60e-d885-42a4-bcef-b915fbd65829", "text": "Hány százalék felel meg a fél (1/2) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "7fec8ad2-7116-4fba-aa46-d30673e3bd87", "text": "Hány százalék felel meg a negyed (1/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "65cecf95-124a-4c2c-a7ea-9aa245cccd54", "text": "Hány százalék felel meg a háromnegyed (3/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "e51f4c1b-8c39-4226-8cab-b2d14e9259cb", "text": "A 10% az egész 1/10-ed részét jelenti.", "type": "true-false", "options": [{"id": "03e73931-b30f-4797-a07c-5b5fa6d083c5", "text": "Igaz", "isCorrect": true}, {"id": "f7b99948-b8f0-4c88-8bda-f55d4c0a9ab2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f7e7f9eb-b430-4acc-9187-3e28ff91ac4e", "text": "A 20% az egész 1/5-öd részének felel meg.", "type": "true-false", "options": [{"id": "33cca52f-378f-4a56-9d48-9584d4fe42e6", "text": "Igaz", "isCorrect": true}, {"id": "caa0c9c5-5668-45f2-ab57-8312b4f1ad1a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5a2be862-9528-4749-965c-2e3f52e72e75', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$82. óra: A százalékszámítás gyakorlása$q$, $q$Százalékérték kiszámítása következtetéssel (1% kiszámítása) vagy törtrésszel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "8470e8d4-79f4-46cc-982b-abef69e18d3c", "text": "Mennyi 500 Ft-nak a 10%-a? (500 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "cb26c2a3-596f-44ea-a519-2dc51e2c6793", "text": "Mennyi 500 Ft-nak az 1%-a? (500 / 100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "8485c1f8-4212-4db4-a04c-247fd95e00e0", "text": "Mennyi 500 Ft-nak a 20%-a? (500 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "8fa45c41-0862-4271-a15a-9baaa269d483", "text": "Mennyi 800 kg-nak az 50%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "db358f26-bf2e-4b47-8a89-c1dde7961595", "text": "A százalékérték kiszámításához az alapmennyiséget megszorozzuk a százaléklábbal és elosztjuk 100-zal.", "type": "true-false", "options": [{"id": "447f5691-1771-4e81-8a55-da2fff4e0841", "text": "Igaz", "isCorrect": true}, {"id": "af7059d5-1f7b-4286-9676-fe9da4a8a6d0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "462dddcc-de91-407b-bd05-6401e48f8246", "text": "Mennyi 200 Ft-nak a 25%-a? (200 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "16188927-cb90-4b7f-a457-1a9c3d699f73", "text": "Mennyi 1000 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1e650d26-b5dc-496c-876c-fd3a473883d7', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$83. óra: Feladatmegoldás$q$, $q$Százalékszámítással kapcsolatos hétköznapi szöveges feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "ed0a5fab-ee5f-4e72-b7b9-e0a67e49269d", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezmény összege? (10000 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "c38569fd-9c4e-4ef4-b07e-63df85983352", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezményes ár? (10000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8000"}, {"id": "f402203b-c7c1-4e49-b889-e1c3ca714f5f", "text": "Egy iskolában 400 tanuló van. 55%-uk lány. Hány lány jár az iskolába? (400 * 0,55)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "220"}, {"id": "e38135b0-317f-4d16-9dbb-bb4931c7253f", "text": "Hány fiú jár az iskolába? (400 - 220)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "89259ff5-e2b4-4b63-b8c8-34bfe0e60aef", "text": "A kedvezményes ár kiszámításához az eredeti árból kivonjuk a kedvezmény értékét.", "type": "true-false", "options": [{"id": "4815bc9b-9a89-415d-94b6-77b6c7763503", "text": "Igaz", "isCorrect": true}, {"id": "ec3a03c5-ed4e-4090-91cb-825371eff426", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9bf8e7b9-c1ff-4daf-8a12-90589c329b54", "text": "Ha egy ár 10%-kal nő, az új ár az eredeti ár 110%-a lesz.", "type": "true-false", "options": [{"id": "1f21295b-cf7e-4a81-aee9-75b08c23146d", "text": "Igaz", "isCorrect": true}, {"id": "40e5e78e-3394-4d79-9039-c58d5d248973", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "85497964-c5cb-4867-a742-e5e44c7c20a7", "text": "Mennyi 50 000 Ft 5%-os kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3b93df94-95a6-448f-9a8c-ae038463f3ad', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$84. óra: Feladatmegoldás II.$q$, $q$Összetettebb százalékszámítási feladatok, árleértékelések, drágulások.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "6cb99815-33a8-4267-a5c5-191b85da5d8a", "text": "Egy 20 000 Ft-os kabát árát 15%-kal felemelték. Hány Ft a drágulás értéke? (20000 * 0,15)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "f7eecf8e-e0a7-4fb7-90f3-29b0d842a91f", "text": "Mennyi a kabát új ára a 15%-os drágulás után? (20000 + 3000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "23000"}, {"id": "c55c7936-da49-4802-ad88-c81adf8d8150", "text": "A 30-as létszámú osztályban a tanulók 10%-a hiányzott. Hány tanuló hiányzott?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "d3aedf57-be0b-4401-8e5c-39830b9292da", "text": "Hány tanuló volt jelen az osztályban? (30 - 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "fe56b691-b1ca-47f3-97c5-c4d3cb662f92", "text": "Ha a 100 Ft-os termék ára 50%-kal csökken, majd a kedvezményes ár 50%-kal nő, az ár visszatér 100 Ft-ra.", "type": "true-false", "options": [{"id": "fe1f80e7-3e94-41cb-8dd3-2e2cfa5abb37", "text": "Igaz", "isCorrect": false}, {"id": "93711e97-1298-4efd-abf4-019d9f06b1c2", "text": "Hamis (50 Ft 50%-os növekedése 75 Ft lesz!)", "isCorrect": true}], "timeLimit": 15}, {"id": "bedfefad-083d-401f-a5e6-ca856cd5d945", "text": "Mennyi 400 liter 75%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "6d538ede-c2f7-450d-b20b-9814a6adf01c", "text": "A százalékszámítás alapvető ismeret a mindennapi pénzügyi tájékozódáshoz.", "type": "true-false", "options": [{"id": "e0d08024-3af9-4f26-a7fd-81136042307b", "text": "Igaz", "isCorrect": true}, {"id": "cad0803f-c517-426b-8569-207240b20543", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b19abcd2-bc43-4cff-a701-5b77fc905cb0', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$85. óra: Projektóra$q$, $q$Családi költségvetés készítése megadott keretből, százalékos megoszlások számítása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "5b7a1542-1aaa-40d5-9dc3-f66b84243475", "text": "Ha a család havi jövedelme 400 000 Ft, és 30%-ot költenek lakhatásra, hány Ft a lakhatási költség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "510af4ed-b7eb-45f4-bed4-529350382d7c", "text": "Ha a jövedelem 40%-át élelmiszerre költik, hány Ft megy élelmiszerre? (400000 * 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "b39cb330-e98e-4527-abb4-62882d0f3c7d", "text": "Hány Ft marad megtakarításra és egyéb kiadásokra? (400000 - 120000 - 160000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "384c8430-5ad1-4a3a-a549-5266252193c7", "text": "A családi költségvetés készítésekor a kiadások összege nem haladhatja meg a bevételeket.", "type": "true-false", "options": [{"id": "366dca0c-21b2-44d5-9b9f-26b88a686689", "text": "Igaz", "isCorrect": true}, {"id": "981f5602-4f4c-4586-a98c-757c51f2f55a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "629c5b05-9f89-4b0c-80c0-734cac50eb05", "text": "Hány százalékot tesz ki a megmaradt 120 000 Ft a 400 000 Ft-os jövedelemből?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "02c8a41f-3e1f-4a47-b23d-2c93e157de7a", "text": "A százalékos megoszlás kördiagramon ábrázolva jól szemlélteti a kiadások arányát.", "type": "true-false", "options": [{"id": "a77c6c03-6c0d-41cc-90a5-1f4e3d39cbb5", "text": "Igaz", "isCorrect": true}, {"id": "43170b18-5e2b-468f-823c-3f5d78605069", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "95724d05-c217-4c24-b726-3ad6ed2b14b5", "text": "A tudatos pénzügyi tervezés segít elkerülni az eladósodást.", "type": "true-false", "options": [{"id": "2ef4a350-ff92-4657-92e7-002f849f0b55", "text": "Igaz", "isCorrect": true}, {"id": "bb444cc3-595c-47ad-84f8-98bd2747c104", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('338cd43b-1ab9-40df-a51b-588d4acbeb83', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$86. óra: Nyitott mondatok$q$, $q$Lebontogatás (visszafelé gondolkodás) és próbálgatás módszere egyenleteknél.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "e083a26b-02ad-46f5-a267-93bc8abf952b", "text": "Mit jelent a lebontogatás (visszafelé gondolkodás) módszere?", "type": "multiple-choice", "options": [{"id": "56ae2483-1bfb-47a6-9c9f-54cadd336c74", "text": "A végeredményből kiindulva az inverz (ellentétes) műveleteket végezzük el visszafelé", "isCorrect": true}, {"id": "337c0242-0f30-482d-9c15-01529f93c6a9", "text": "Visszafelé írjuk le a számokat", "isCorrect": false}, {"id": "8b962347-6ff1-466d-a1a8-f3c78fe1767c", "text": "Tippelünk egy számot és feladjuk", "isCorrect": false}, {"id": "7038ef11-9cc4-427b-be0c-6c41208442d8", "text": "Kivonunk mindent 100-ból", "isCorrect": false}], "timeLimit": 15}, {"id": "b3c5a1f4-b6f8-4871-b3fd-b8cf7b21086d", "text": "Melyik szám teszi igazzá: 2 * x + 5 = 17? (17 - 5 = 12, 12 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "f81f7e54-eadd-4a7d-b07b-2c2ad5ffe016", "text": "Melyik szám teszi igazzá: (y - 4) : 3 = 5? (5 * 3 = 15, 15 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "19"}, {"id": "32800a52-37c7-431e-b09b-bf2e306e41e2", "text": "Az ellenőrzés során a kapott értéket behelyettesítjük az eredeti nyitott mondatba.", "type": "true-false", "options": [{"id": "2524cd3f-985c-4e24-a7e7-e977e091b214", "text": "Igaz", "isCorrect": true}, {"id": "222e637b-c317-4ee8-99ed-0f934024baea", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1d9e6569-a89f-4860-9516-c8f1139f26cb", "text": "Melyik szám teszi igazzá: 3 * a - 10 = 20?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "7bf5bfbc-fe04-4c2f-8692-9b8af4c4fada", "text": "A próbálgatásos módszernél rendszerezett táblázatot érdemes vezetni.", "type": "true-false", "options": [{"id": "7b83ca46-2ec7-4df0-9b8e-3d1269b334f7", "text": "Igaz", "isCorrect": true}, {"id": "d2e33cf9-d66c-4627-aa59-08ec811e0d24", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a23d2f87-3f0e-4f62-9ded-9d66b73dc700", "text": "Melyik szám teszi igazzá: x / 4 + 2 = 7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ef2f0c74-a60a-4f38-94f6-7f482c782d8f', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$87. óra: Feladatmegoldás: Nyitott mondatok$q$, $q$Gyakorlás: lebontogatási módszer alkalmazása egyenletek és egyenlőtlenségek megoldásában.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "61890d14-9ab6-4373-affe-fe0ce54abad4", "text": "Melyik szám teszi igazzá: 4 * (x + 2) = 36? (36/4 = 9, 9-2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "458e6505-ebb0-4126-8a87-4ac060ae64a8", "text": "Melyik szám teszi igazzá: 5 * y - 12 = 38? (50/5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "7754ac54-5011-4f21-a330-2da19a50064c", "text": "Ha az alaphalmaz a természetes számok (0, 1, 2, ...), hány megoldása van a 2 * x < 6 egyenlőtlenségnek? (x = 0, 1, 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "b0402a10-0b66-4cb3-a059-14402d098eb9", "text": "Az egyenlőtlenségeknek több megoldása is lehet egy megadott alaphalmazon.", "type": "true-false", "options": [{"id": "7cc562ce-3994-4417-ae4a-a016cb3cef24", "text": "Igaz", "isCorrect": true}, {"id": "8f4207ce-dafd-4e01-95bd-63439611180f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a2775361-9d7d-400e-a043-a5bfb2bb0fe9", "text": "Melyik szám teszi igazzá: (z + 10) / 2 = 15?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "245457e4-401b-40fd-b379-e74505d10b08", "text": "Ha az egyenletnek nincs megoldása az adott alaphalmazon, az igazsághalmaz az üres halmaz.", "type": "true-false", "options": [{"id": "1783eb6c-5d37-4c7f-a3e8-1e19b1d37da9", "text": "Igaz", "isCorrect": true}, {"id": "6b04cd9f-4acf-4a67-85c0-eac4b6266cc3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ef92c287-9ff9-484c-95c8-b32eb368bc5d", "text": "Melyik szám teszi igazzá: 10 * x - 25 = 75?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f8951c6d-1915-40c1-a32a-a990b6915f59', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$88. óra: Gyakorlóóra$q$, $q$Nyitott mondatok és műveleti sorrend gyakorlása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "58ec5698-8124-4937-9082-619ea080e599", "text": "Melyik szám teszi igazzá: 3 * x + 7 = 34?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "383292e9-c3ac-4031-93a7-f78cd6734977", "text": "Melyik szám teszi igazzá: (x - 5) * 6 = 42?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "21bb960e-6788-4cb3-a0e0-334ec92f3d87", "text": "A lebontogatás lépései során az utolsóként elvégzett művelet inverzével kezdjük a számolást.", "type": "true-false", "options": [{"id": "856f52f5-9a38-48ac-bc40-bbcab025a63a", "text": "Igaz", "isCorrect": true}, {"id": "210d5389-2518-487d-8735-5aa1bb951a5e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "06aa3d19-3a7e-4a2c-819d-cdd25497e867", "text": "Mennyi x értéke, ha 50 - 2 * x = 30? (2x = 20)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "37eddd6b-df1a-4123-a617-971752de5429", "text": "Mennyi y értéke, ha y / 3 - 4 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "98af0fc3-a4b5-4379-89f6-39ec4f22b75f", "text": "Az ellenőrzés kihagyása növeli a hibázás kockázatát.", "type": "true-false", "options": [{"id": "78c69d20-578d-459a-987f-8f37f142ba03", "text": "Igaz", "isCorrect": true}, {"id": "ffce8477-dede-4470-95d3-845bdc72b1c7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "43021c3d-20e5-4da0-b0e4-af7ce11bcf76", "text": "Melyik szám teszi igazzá: 8 * a + 4 = 68?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6ed21c67-fb35-4955-97d8-bbaa828f9d07', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$89. óra: Szöveges feladatok$q$, $q$Szöveges feladatok megoldása nyitott mondatok felírásával, ábrakészítéssel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "c3a17255-88dd-4c5a-a9b1-fcfab573df23", "text": "Gondoltam egy számot, megszóroztam 3-mal, hozzáadtam 12-őt és 45-öt kaptam. Mi volt a szám? (3x + 12 = 45 -> 3x = 33)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "950c2cea-e5e7-4035-8f15-7af702ce44a8", "text": "Gondoltam egy számot, kivontam belőle 8-at, megszoroztam 4-gyel és 40-et kaptam. Mi volt a szám? ((x-8)*4 = 40 -> x-8 = 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "f159d30d-6e9a-4968-8fd2-f2e5035a5309", "text": "Katinak 3-szor annyi matricája van, mint Petinek. Összesen 48 matricájuk van. Hány matricája van Petinek? (x + 3x = 48 -> 4x = 48)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "f84d3e93-6eff-4edd-83bc-f4e0e080073d", "text": "Hány matricája van Katinak? (3 * 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "3ca81059-4e26-4162-bf2b-7b27bf5fbbf5", "text": "A szöveges feladatok megoldásának lépései: Értelmezés -> Adatok/Ismeretlen -> Nyitott mondat -> Számolás -> Ellenőrzés -> Válaszmondat.", "type": "true-false", "options": [{"id": "e0f4d694-ab25-48c2-a9f9-00d043aed5f6", "text": "Igaz", "isCorrect": true}, {"id": "b1f988cc-9147-4c3d-abc8-5d48200a9331", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b15d587c-ac8d-4cd5-b1fe-38bb6910d37a", "text": "Ha a feladatban a 'kétszer annyi' kifejezés szerepel, 2-vel való szorzásra gondolunk.", "type": "true-false", "options": [{"id": "abbe9706-484f-4c2e-b848-fe0c05b83a4a", "text": "Igaz", "isCorrect": true}, {"id": "92775181-7fee-46fa-8ab7-0c7ff4dcaebe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bad8012a-fd8a-49a5-9e68-8aa4fdce0ac5", "text": "Gondoltam egy számot, elosztottam 5-tel, hozzáadtam 7-et és 12-őt kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ec56d90b-d60f-4e8f-b908-11d12e423bb8', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$90. óra: Gyakorlóóra$q$, $q$Matematikai szövegezésű feladatok gyakorlása, ábrakészítés, összefüggések.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "00eea9ac-1ed7-4b79-aff8-0e52c92ef467", "text": "Apa 4 évvel idősebb, mint Anya. Életkoruk összege 76 év. Hány éves Anya? (2x + 4 = 76 -> 2x = 72)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "5b1c6c34-b510-4b9b-a286-74a0db2eec80", "text": "Hány éves Apa? (36 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "bc1065b4-1285-418e-b68c-2b0eec643bc0", "text": "Egy téglalap kerülete 40 cm. Hosszabbik oldala 4 cm-rel hosszabb a rövidebbnél. Hány cm a rövidebb oldal? (2*(x + x+4) = 40 -> 4x + 8 = 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "fd2e9b3b-57ca-4635-84ee-7f209c6c6e1a", "text": "Hány cm a hosszabbik oldal? (8 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "231a7ed4-fdd0-4c63-b66c-32d520176bda", "text": "A szakaszos ábrázolás nagymértékben segít a szöveges feladatok összefüggéseinek megértésében.", "type": "true-false", "options": [{"id": "95b26dfe-cffe-4fee-afdc-0970b13b9faa", "text": "Igaz", "isCorrect": true}, {"id": "6178c7f7-2375-4f98-ae90-1d4ac48003c5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d127906-19c4-46ff-85cc-f6c223271695", "text": "Három egymást követő egész szám összege 45. Mi a legkisebb szám? (x + x+1 + x+2 = 45 -> 3x + 3 = 45)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "9237b3a1-4b13-48f6-ad84-ef0bae7c63b9", "text": "A válaszmondat felírása kötelező a szöveges feladat végén.", "type": "true-false", "options": [{"id": "a472446f-4c05-4f80-a33d-64624f9ae3c2", "text": "Igaz", "isCorrect": true}, {"id": "36dde347-ebbd-4534-be4d-00387f7ccb9e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;